/* QMES sidebar outside-click compatibility stub.
 * Intentionally disabled: page controls must receive their first click while the sidebar is open.
 * The sidebar closes only through its own close control or an explicit menu action.
 */
(function disableSidebarOutsideClickClose(){
  "use strict";
  window.__QMES_SIDEBAR_OUTSIDE_CLICK_CLOSE__ = true;
})();
